import sqlite3
import unittest

import database


LEGACY_EVENTS_SQL = '''CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY,
    series_id INTEGER NOT NULL REFERENCES series(id),
    start_time TEXT NOT NULL,
    end_time TEXT NOT NULL,
    end_is_estimated INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'open'
        CHECK (status IN ('open','apply','members_only','ongoing','full','closed')),
    UNIQUE (series_id,start_time)
)'''

PROVENANCE_INSERT = '''INSERT INTO event_provenance
    (event_id,kind,forecast_anchor_date,evidence_weeks,created_at,verification_url,verified_at)
    VALUES (?,?,?,?,?,?,?)'''


class ForecastMigrationTests(unittest.TestCase):
    """Upgrade a real legacy fixture without resetting events, plans or source observations."""

    def connection(self, legacy=False):
        """Create an isolated project database with either the current or original event table."""
        connection = database.get_connection(':memory:')
        self.addCleanup(connection.close)
        if legacy:
            with connection:
                for statement in database.SCHEMA.split(';'):
                    if 'CREATE TABLE IF NOT EXISTS event_provenance (' in statement:
                        continue
                    if 'CREATE TABLE IF NOT EXISTS events (' in statement:
                        connection.execute(LEGACY_EVENTS_SQL)
                    elif statement.strip():
                        connection.execute(statement)
        else:
            database.init_db(connection)
        self.seed(connection)
        return connection

    def seed(self, connection):
        """Use deliberately sparse IDs and genuine foreign-key references in synthetic records."""
        with connection:
            connection.execute('''INSERT INTO directions (id,key,name,sort_order)
                VALUES (3,'sports','Sports',1)''')
            connection.execute('''INSERT INTO bundles
                (id,key,direction_id,name,is_other,sort_order)
                VALUES (5,'sports_other',3,'Other',1,1)''')
            connection.execute('''INSERT INTO series
                (id,source,external_id,title,bundle_id,location_type)
                VALUES (17,'unisport','fixture-course','Fixture course',5,'tba')''')
            connection.executemany('''INSERT INTO events
                (id,series_id,start_time,end_time,status) VALUES (?,17,?,?,?)''',
                [(42, '2026-11-16 08:00:00', '2026-11-16 09:00:00', 'open'),
                 (900, '2026-11-17 08:00:00', '2026-11-17 09:00:00', 'closed')])
            connection.executemany('''INSERT INTO users
                (id,display_name,friend_code,is_synthetic,created_at) VALUES (?,?,?,0,?)''',
                [(23, 'Test A', 'TESTA1', '2026-11-15 10:00:00'),
                 (77, 'Test B', 'TESTB1', '2026-11-15 10:00:00')])
            connection.execute('''INSERT INTO interactions
                (id,user_id,event_id,status,confirmed_at)
                VALUES (301,23,42,'confirmed','2026-11-15 10:00:00')''')
            connection.execute('''INSERT INTO invitations
                (id,sender_id,recipient_id,event_id,status,created_at)
                VALUES (902,23,77,900,'pending','2026-11-15 10:00:00')''')
            connection.execute('''INSERT INTO training_imports
                (id,file_name,source_fingerprint,imported_at)
                VALUES (8,'fixture.csv','fixture-fingerprint','2026-11-15 10:00:00')''')
            connection.execute('''INSERT INTO training_history
                (id,import_id,source_row,sport,weekday_text,start_time,date_original,training_date,
                 participants_signed_up,participants_teacher,max_participants)
                VALUES (61,8,2,'Yoga','Friday','08:00','Freitag, 6. November 2026',
                        '2026-11-06',0,3,9999)''')

    def snapshots(self, connection):
        """Capture complete row contents with fixed SQL so migration loss is detectable."""
        queries = ['SELECT * FROM series ORDER BY id', 'SELECT * FROM events ORDER BY id',
                   'SELECT * FROM users ORDER BY id', 'SELECT * FROM interactions ORDER BY id',
                   'SELECT * FROM invitations ORDER BY id',
                   'SELECT * FROM training_imports ORDER BY id',
                   'SELECT * FROM training_history ORDER BY id']
        result = []
        for query in queries:
            result.append([tuple(row) for row in connection.execute(query).fetchall()])
        return result

    def scalar(self, connection, sql, params=()):
        """Read one value from a fixed assertion query."""
        return connection.execute(sql, params).fetchone()[0]

    def add_standalone_event(self, connection):
        """Add an event with no personal references for metadata deletion checks."""
        with connection:
            connection.execute('''INSERT INTO events
                (id,series_id,start_time,end_time,status)
                VALUES (888,17,'2026-11-24 08:00:00','2026-11-24 09:00:00','unknown')''')

    def projected(self, event_id=42):
        """Return complete synthetic evidence for a provisional event."""
        return [event_id, 'projected', '2026-11-06', 3, '2026-11-15 10:00:00', None, None]

    def test_legacy_migration_retains_ids_rows_references_and_constraints(self):
        """Upgrade populated old storage and accept unknown without weakening foreign keys."""
        connection = self.connection(legacy=True)
        before = self.snapshots(connection)
        database.init_db(connection)
        self.assertEqual(self.snapshots(connection), before)
        self.assertEqual(self.scalar(connection, 'PRAGMA foreign_keys'), 1)
        self.assertEqual(self.scalar(connection, 'PRAGMA legacy_alter_table'), 0)
        self.assertFalse(connection.execute('PRAGMA foreign_key_check').fetchall())
        self.assertEqual(self.scalar(connection, 'SELECT COUNT(*) FROM event_provenance'), 0)
        self.add_standalone_event(connection)
        with self.assertRaises(sqlite3.IntegrityError), connection:
            connection.execute("UPDATE events SET status='invented' WHERE id=888")
        with self.assertRaises(sqlite3.IntegrityError), connection:
            connection.execute('''INSERT INTO events
                (series_id,start_time,end_time,status)
                VALUES (999,'2026-12-01 08:00:00','2026-12-01 09:00:00','unknown')''')
        after = self.snapshots(connection)
        database.init_db(connection)
        self.assertEqual(self.snapshots(connection), after)
        self.assertFalse(database.migrate_event_status(connection))

    def test_custom_index_trigger_and_view_survive_without_firing(self):
        """Retain schema objects and only trigger an audit when a later user update occurs."""
        connection = self.connection(legacy=True)
        with connection:
            connection.execute('CREATE INDEX event_status_index ON events(status)')
            connection.execute('CREATE TABLE event_audit (event_id INTEGER, status TEXT)')
            connection.execute('''CREATE TRIGGER event_status_audit AFTER UPDATE OF status
                ON events BEGIN
                    INSERT INTO event_audit (event_id,status) VALUES (NEW.id,NEW.status);
                END''')
            connection.execute('CREATE VIEW event_times AS SELECT id,start_time FROM events')
        before_view = [tuple(row) for row in connection.execute('SELECT * FROM event_times')]
        database.init_db(connection)
        self.assertEqual([tuple(row) for row in connection.execute('SELECT * FROM event_times')],
                         before_view)
        self.assertEqual(self.scalar(connection, 'SELECT COUNT(*) FROM event_audit'), 0)
        self.assertEqual(self.scalar(connection, '''SELECT COUNT(*) FROM sqlite_master
            WHERE type='index' AND name='event_status_index' '''), 1)
        with connection:
            connection.execute("UPDATE events SET status='unknown' WHERE id=42")
        self.assertEqual([tuple(row) for row in connection.execute('SELECT * FROM event_audit')],
                         [(42, 'unknown')])

    def test_failure_after_drop_rolls_back_schema_rows_and_restores_flags(self):
        """Deny the final rename and restore even the previously dropped legacy table."""
        for legacy_flag in (0, 1):
            with self.subTest(legacy_alter_table=legacy_flag):
                connection = self.connection(legacy=True)
                connection.execute('PRAGMA legacy_alter_table = ON' if legacy_flag else
                                   'PRAGMA legacy_alter_table = OFF')
                before = self.snapshots(connection)
                schema = self.scalar(connection, '''SELECT sql FROM sqlite_master
                    WHERE type='table' AND name='events' ''')

                def deny_rename(action, first, second, db_name, trigger):
                    """Simulate an engine failure after the migration has copied and dropped."""
                    return sqlite3.SQLITE_DENY if action == sqlite3.SQLITE_ALTER_TABLE else \
                        sqlite3.SQLITE_OK

                connection.set_authorizer(deny_rename)
                try:
                    with self.assertRaises(sqlite3.DatabaseError):
                        database.init_db(connection)
                finally:
                    connection.set_authorizer(None)
                self.assertEqual(self.snapshots(connection), before)
                self.assertEqual(self.scalar(connection, '''SELECT sql FROM sqlite_master
                    WHERE type='table' AND name='events' '''), schema)
                self.assertEqual(self.scalar(connection, 'PRAGMA foreign_keys'), 1)
                self.assertEqual(self.scalar(connection, 'PRAGMA legacy_alter_table'), legacy_flag)
                self.assertFalse(connection.in_transaction)
                self.assertEqual(self.scalar(connection, '''SELECT COUNT(*) FROM sqlite_master
                    WHERE name='events_status_upgrade' '''), 0)

    def test_pending_caller_transaction_is_not_committed(self):
        """Refuse migration while leaving unrelated pending changes under caller control."""
        connection = self.connection(legacy=True)
        before = self.snapshots(connection)
        connection.execute("INSERT INTO app_settings (key,value) VALUES ('pending','yes')")
        with self.assertRaises(ValueError):
            database.init_db(connection)
        self.assertTrue(connection.in_transaction)
        self.assertEqual(self.scalar(connection,
                                     "SELECT COUNT(*) FROM app_settings WHERE key='pending'"), 1)
        connection.rollback()
        self.assertEqual(self.scalar(connection, 'SELECT COUNT(*) FROM app_settings'), 0)
        self.assertEqual(self.snapshots(connection), before)
        self.assertEqual(self.scalar(connection, 'PRAGMA foreign_keys'), 1)

    def test_unrecognized_schema_is_refused_without_losing_extra_columns(self):
        """Do not rebuild an event table carrying data this migration does not understand."""
        connection = self.connection(legacy=True)
        with connection:
            connection.execute('ALTER TABLE events ADD COLUMN private_note TEXT')
            connection.execute("UPDATE events SET private_note='retain me' WHERE id=42")
        before = self.snapshots(connection)
        with self.assertRaises(ValueError):
            database.init_db(connection)
        self.assertEqual(self.snapshots(connection), before)
        self.assertEqual(self.scalar(connection, 'PRAGMA foreign_keys'), 1)

    def test_existing_orphans_and_staging_objects_prevent_migration(self):
        """Preserve anomalous storage for explicit review instead of changing it silently."""
        connection = self.connection(legacy=True)
        connection.execute('PRAGMA foreign_keys = OFF')
        with connection:
            connection.execute('''INSERT INTO events
                (id,series_id,start_time,end_time)
                VALUES (701,999,'2026-12-02 08:00:00','2026-12-02 09:00:00')''')
        connection.execute('PRAGMA foreign_keys = ON')
        before = self.snapshots(connection)
        with self.assertRaises(ValueError):
            database.init_db(connection)
        self.assertEqual(self.snapshots(connection), before)
        other = self.connection(legacy=True)
        with other:
            other.execute('CREATE TABLE events_status_upgrade (sentinel TEXT)')
            other.execute("INSERT INTO events_status_upgrade VALUES ('retain')")
        with self.assertRaises(ValueError):
            database.init_db(other)
        self.assertEqual(self.scalar(other, 'SELECT sentinel FROM events_status_upgrade'), 'retain')

    def test_projected_provenance_requires_observed_weeks_and_no_web_claim(self):
        """Accept complete evidence and reject missing, insufficient or fractional evidence."""
        connection = self.connection()
        invalid = []
        for value in (None, 0, 2, 5, 3.5):
            row = self.projected()
            row[3] = value
            invalid.append(row)
        for index, value in ((2, None), (2, ''), (5, 'https://example.org'),
                             (6, '2026-11-15 10:00:00')):
            row = self.projected()
            row[index] = value
            invalid.append(row)
        for row in invalid:
            with self.subTest(values=row), self.assertRaises(sqlite3.IntegrityError), connection:
                connection.execute(PROVENANCE_INSERT, row)
        with connection:
            connection.execute(PROVENANCE_INSERT, self.projected())
        self.assertEqual(self.scalar(connection, 'SELECT COUNT(*) FROM event_provenance'), 1)
        with self.assertRaises(sqlite3.IntegrityError), connection:
            connection.execute(PROVENANCE_INSERT, self.projected(999))

    def test_website_provenance_requires_https_source_and_check_time(self):
        """Keep a website assertion separate from forecast evidence and event availability."""
        connection = self.connection()
        valid = [42, 'website', None, None, '2026-11-15 10:00:00',
                 'https://example.org/public-course', '2026-11-15 10:00:00']
        for index, value in ((5, None), (5, ''), (5, 'http://example.org'),
                             (5, 'https://'), (6, None), (6, '')):
            row = list(valid)
            row[index] = value
            with self.subTest(index=index, value=value):
                with self.assertRaises(sqlite3.IntegrityError), connection:
                    connection.execute(PROVENANCE_INSERT, row)
        with connection:
            connection.execute(PROVENANCE_INSERT, valid)
        self.assertEqual(self.scalar(connection, 'SELECT kind FROM event_provenance'), 'website')
        self.assertEqual(self.scalar(connection, 'SELECT status FROM events WHERE id=42'), 'open')

    def test_event_deletion_cascades_only_its_metadata(self):
        """Remove stale event provenance without touching source observations or other plans."""
        connection = self.connection()
        self.add_standalone_event(connection)
        with connection:
            connection.execute(PROVENANCE_INSERT, self.projected(888))
            connection.execute('DELETE FROM events WHERE id=888')
        self.assertEqual(self.scalar(connection, 'SELECT COUNT(*) FROM event_provenance'), 0)
        self.assertEqual(self.scalar(connection, 'SELECT COUNT(*) FROM interactions'), 1)
        self.assertEqual(self.scalar(connection, 'SELECT COUNT(*) FROM training_history'), 1)

    def test_demo_reset_preserves_the_private_archive(self):
        """Reset only app/demo data while retaining all original training rows and import IDs."""
        connection = self.connection()
        history = [tuple(row) for row in connection.execute('SELECT * FROM training_history')]
        imports = [tuple(row) for row in connection.execute('SELECT * FROM training_imports')]
        with connection:
            connection.execute(PROVENANCE_INSERT, self.projected())
        database.reset_database(connection)
        stored_history = connection.execute('SELECT * FROM training_history').fetchall()
        stored_imports = connection.execute('SELECT * FROM training_imports').fetchall()
        self.assertEqual([tuple(row) for row in stored_history], history)
        self.assertEqual([tuple(row) for row in stored_imports], imports)
        self.assertEqual(self.scalar(connection, 'SELECT COUNT(*) FROM event_provenance'), 0)
        self.assertEqual(self.scalar(connection, 'SELECT COUNT(*) FROM events'), 0)
        self.assertEqual(self.scalar(connection, 'PRAGMA foreign_keys'), 1)
